def choose_move(observation):
    x, y = observation.get('self_position', (0, 0))
    w = observation.get('grid_width', 3)
    h = observation.get('grid_height', 3)

    # helper to clamp and return a move
    def mv(dx, dy):
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        return [dx, dy]

    # Move toward closest resource if any
    resources = observation.get('resources', [])
    if resources:
        best = None
        bestd = None
        for r in resources:
            rx, ry = r.get('x', x), r.get('y', y)
            d = abs(rx - x) + abs(ry - y)
            if bestd is None or d < bestd:
                bestd = d
                best = (rx, ry)
        if best is not None:
            return mv(best[0] - x, best[1] - y)

    # Move toward closest opponent if present
    opponent = observation.get('opponent_position')
    if opponent is not None:
        ox, oy = opponent
        return mv(ox - x, oy - y)

    # Stay within bounds when no targets
    nx, ny = x, y
    if x < 0:
        nx = 0
    if y < 0:
        ny = 0
    if x > w - 1:
        nx = w - 1
    if y > h - 1:
        ny = h - 1
    return mv(nx - x, ny - y)
